import{_ as s,C as n,o as i,c as r,j as t,a as o,E as l,a6 as h}from"./chunks/framework.CCKCzdWs.js";const w=JSON.parse('{"title":"CI merge gate","description":"What piwi gate decides about a Playwright run: the rules that fail a merge, the ones that only warn, what it leaves out, and how its verdict reaches the pull request.","frontmatter":{"title":"CI merge gate","description":"What piwi gate decides about a Playwright run: the rules that fail a merge, the ones that only warn, what it leaves out, and how its verdict reaches the pull request.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/merge-gate.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/merge-gate.html"}],["meta",{"property":"og:title","content":"CI merge gate | Piwi for Playwright"}],["meta",{"property":"og:description","content":"What piwi gate decides about a Playwright run: the rules that fail a merge, the ones that only warn, what it leaves out, and how its verdict reaches the pull request."}]]},"headers":[],"relativePath":"features/merge-gate.md","filePath":"features/merge-gate.md","lastUpdated":1795606445000}'),d={name:"features/merge-gate.md"};function c(u,e,p,g,f,m){const a=n("Needs");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"ci-merge-gate",tabindex:"-1"},[o("CI merge gate "),t("a",{class:"header-anchor",href:"#ci-merge-gate","aria-label":'Permalink to "CI merge gate"'},"​")],-1)),l(a,{reporter:""}),e[1]||(e[1]=h(`<p>The CI merge gate fails a CI job on the dashboard&#39;s analysis of a run, not on Playwright&#39;s exit code. <code>npx playwright test</code> exits non-zero when anything failed; whether the change broke something that was working, whether a critical test failed or a new root cause appeared needs the run history, so the dashboard evaluates a policy the pipeline declares and <code>piwi gate</code> turns its verdict into an exit code. The reporter never fails a build on its own: the policy belongs to the pipeline.</p><h2 id="turn-it-on-in-ci" tabindex="-1">Turn it on in CI <a class="header-anchor" href="#turn-it-on-in-ci" aria-label="Permalink to &quot;Turn it on in CI&quot;">​</a></h2><p>Record which run to gate on, then run the gate after the tests, whatever their outcome:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npx playwright test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    PIWI_DASHBOARD_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://piwi.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    PIWI_OUTPUT_FILE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">piwi-run.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npx @piwitests/reporter gate --require-tag @critical --max-new-regressions 0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">always()</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    PIWI_DASHBOARD_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://piwi.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    PIWI_API_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ secrets.PIWI_API_KEY }}</span></span></code></pre></div><p>The full recipe and the output a failed gate prints are in <a href="/guide/ci.html#blocking-a-merge">CI &amp; sharding</a>; every flag, default and exit code is in the <a href="/reference/cli.html#gate">CLI reference</a>. The policy needs at least one rule or one warn-only flag, or the gate refuses to run.</p><h2 id="what-fails-it" tabindex="-1">What fails it <a class="header-anchor" href="#what-fails-it" aria-label="Permalink to &quot;What fails it&quot;">​</a></h2><p>Each flag is one rule, and the gate evaluates every rule it was given, so a failed verdict lists everything that is wrong, not only the first rule to trip. The rules bound:</p><ul><li><strong>Failures</strong>: the tests that failed for good (<code>--max-failed</code>), counted once per test however many Playwright projects or attempts failed it; a test that passed on a retry did not fail.</li><li><strong>New regressions and newly flaky tests</strong> (<code>--max-new-regressions</code>, <code>--max-new-flaky</code>): tests failing now that passed in the <a href="/guide/concepts.html#baseline-last-green-run">baseline</a>, and tests that started passing only on a retry.</li><li><strong>Required tests</strong>: every test carrying a tag (<code>--require-tag</code>) must pass, a pass on a retry included. A tag no test of the run carries is a violation in itself, so a misspelled tag cannot pass.</li><li><strong>A selection</strong> (<code>--require-selection</code>): the dashboard resolves the <a href="/features/test-selection.html#guard-it-in-ci">selection</a>&#39;s current definition and fails when a test it matches did not run, was only skipped, or failed. A selection that matches no test fails too.</li><li><strong>Flakiness</strong> (<code>--fail-on-flaky</code>): any test of the run that passed after an earlier attempt failed.</li><li><strong>New failure clusters</strong> (<code>--fail-on-new-cluster</code>): a <a href="/features/failure-clusters.html">cluster</a> first seen in this run.</li><li><strong>Quarantine debt</strong> (<code>--max-quarantined</code>): how many tests the project holds in quarantine, whatever this run did.</li><li><strong>Leaks</strong> (<code>--max-leaks</code>, <code>--max-new-leaks</code>): the browsers, contexts, pages and API request contexts the run left open, counted per opening line (never a server or a process left running), and those no earlier run of the base branch showed (<a href="/features/leak-history.html">leak history</a>). A run that sent no resource report (the capture fixtures missing, <code>captureResources</code> off, or a reporter older than 0.45) fails a leak rule rather than passing on silence, and so does a run of a project that <a href="/operate/capabilities.html#declining-a-capability">declined</a> the Resources capability, whose leaks are not measured.</li><li><strong>Pass reuse</strong> (<code>--max-reused</code>, <code>--require-executed</code>): how many tests the run <a href="/features/reuse-forecast.html#skipping-reusable-tests">reused</a> from earlier passes, by count or share, and the tags whose tests must have executed. In a run that passed with no run error, a reused test counts as passed for <code>--require-tag</code> and <code>--require-selection</code>, unless a <code>--require-executed</code> tag names it. A run that claimed a plan whose reused tests could not be recorded fails every reuse rule.</li></ul><h2 id="what-only-warns" tabindex="-1">What only warns <a class="header-anchor" href="#what-only-warns" aria-label="Permalink to &quot;What only warns&quot;">​</a></h2><p>Two flags report and never fail: they change neither the verdict nor the exit code.</p><ul><li><code>--max-uncovered-changes &lt;n&gt;</code> warns when more than <em>n</em> changed files are <a href="/features/uncovered-changes.html">uncovered changes</a>, naming up to five of them.</li><li><code>--min-patch-coverage &lt;percent&gt;</code> warns when fewer of the change&#39;s added and modified lines ran in the head commit&#39;s <a href="/features/combined-coverage.html">combined coverage</a>, or when that coverage counts none of them.</li></ul><p>Either warns too when the run has no source control diff to count, or when reading the change failed. Without them, the gate ignores uncovered changes.</p><h2 id="what-it-leaves-out" tabindex="-1">What it leaves out <a class="header-anchor" href="#what-it-leaves-out" aria-label="Permalink to &quot;What it leaves out&quot;">​</a></h2><ul><li><strong>Quarantined tests.</strong> A <a href="/features/flaky-tests.html#quarantine-with-a-way-out">quarantined</a> test still runs and reports, and the gate says how many failing tests quarantine excluded. It counts toward no failure, new regression, newly flaky, required tag or selection rule. <code>--fail-on-flaky</code> reads the run&#39;s flaky count and <code>--fail-on-new-cluster</code> its new clusters, quarantined tests included.</li><li><strong>Environment incidents.</strong> A run flagged as an <a href="/features/environment-incidents.html">environment incident</a>, by its rules or by hand, gets the verdict <strong>inconclusive</strong> whatever the policy, with no violation listed: its failures say nothing about the change. The gate exits <code>3</code>, so a pipeline can re-run instead of blaming the change.</li><li><strong>Runs it does not judge.</strong> A run still running or in its global setup is refused, and so is a run the caller cannot see, such as another person&#39;s <a href="/reference/test-metadata.html#run-origin">run requested from the dashboard</a>: the gate exits <code>2</code>, as it does when it cannot reach the dashboard, so a broken pipeline never passes. Any other run is judged as it is, whatever launched it.</li></ul><h2 id="the-verdict" tabindex="-1">The verdict <a class="header-anchor" href="#the-verdict" aria-label="Permalink to &quot;The verdict&quot;">​</a></h2><p>The gate prints one summary line of counts, each violation, each warning and the run&#39;s link. With <code>--json</code> it prints the result instead: <code>verdict</code> (<code>passed</code>, <code>failed</code> or <code>inconclusive</code>), <code>passed</code>, <code>violations</code> (each with a stable <code>rule</code> id a pipeline can branch on, its message, and for a threshold the value and the limit), the measured <code>facts</code> and any <code>warnings</code>. An inconclusive result carries <code>passed: false</code> and the incident under <code>facts.incident</code>, so a client that reads only <code>passed</code> still blocks the merge. Evaluating never changes the run.</p><h2 id="on-the-pull-request" tabindex="-1">On the pull request <a class="header-anchor" href="#on-the-pull-request" aria-label="Permalink to &quot;On the pull request&quot;">​</a></h2><p>An evaluation made with a key that can upload or control the project&#39;s runs (Uploader, Maintainer and above, the CI key <code>piwi gate</code> uses) is stored with its policy, its verdict, its violations and warnings, and the pull request it judged. Any other reader of the project gets the verdict only: nothing is stored or posted.</p><ul><li><strong>A commit status of its own.</strong> Turn on <strong>Gate status</strong> under <strong>Project → Settings → Source control</strong>, and each stored verdict is also posted as your status context plus <code>/gate</code> (<code>piwi/tests/gate</code>): green with <em>Gate policy satisfied</em>, red with the first violation. A branch rule can then require the gate rather than the run. It needs <a href="/features/pr-feedback.html#turn-it-on">pull-request feedback</a> on, with <strong>Set a commit status</strong>, and <code>PIWI_SITE_URL</code> set, since the status links the run. An inconclusive verdict posts nothing.</li><li><strong>Overrides and escapes.</strong> Every ten minutes Piwi asks the host what became of the pull requests a gate failed on. One merged while its last evaluation still failed counts as an override; one fixed first, or closed, does not. When a cluster that evaluation caught as a new regression fails again on an eligible default-branch run within 30 days of the merge, the override also counts as an escape past the gate.</li></ul><p>The pull-request comment reports a run&#39;s failures; it never blocks a merge. The gate does.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/ci.html#blocking-a-merge">CI &amp; sharding</a>: the gate in a CI job, and its output</li><li><a href="/reference/cli.html#gate">Piwi CLI</a>: every flag, default and exit code</li><li><a href="/features/pr-feedback.html">Pull-request feedback</a>: the comment and commit status of a run</li><li><a href="/features/flaky-tests.html#quarantine-with-a-way-out">Flaky tests &amp; quarantine</a>: what quarantine leaves out</li><li><a href="/features/environment-incidents.html">Environment incidents</a>: the runs the gate calls inconclusive</li></ul>`,22))])}const y=s(d,[["render",c]]);export{w as __pageData,y as default};
